/* ── A generic entity: a mail relay the workspace and an organisation configure ── */
interface RelayValues {
  general: {
    name: string;
    hidden: boolean;
  };
  connection: {
    host: string;
    port: number | null;
    username: string;
    password: SecretValue;
  };
  policy: {
    retry: boolean | null;
    dailyLimit: number | null;
  };
}

const SAVED: RelayValues = {
  general: { name: "Cedar Annex SMTP relay", hidden: false },
  connection: {
    host: "smtp.northstar.example",
    port: 587,
    username: "glass-ux-alerts",
    password: secretValue(true),
  },
  policy: { retry: null, dailyLimit: 2000 },
};
const relaySchema = z
  .object({
    general: z.object({
      name: z.string().trim().min(1, "Enter a name").max(64, "Use 64 characters or fewer"),
      hidden: z.boolean(),
    }),
    connection: z.object({
      host: z.string().trim().min(1, "Enter the mail server's host name"),
      port: z
        .number({ error: "Enter a port from 1 to 65535" })
        .int()
        .min(1, "Enter a port from 1 to 65535")
        .max(65535, "Enter a port from 1 to 65535")
        .nullable(),
      username: z.string(),
      password: z.object({
        stored: z.boolean(),
        action: z.enum(["keep", "replace", "clear"]),
        value: z.string(),
      }),
    }),
    policy: z.object({
      retry: z.boolean().nullable(),
      dailyLimit: z.number().int().min(1, "Allow at least one message a day").nullable(),
    }),
  })
  .superRefine((values, context) => {
    if (values.connection.port === null)
      context.addIssue({
        code: "custom",
        path: ["connection", "port"],
        message: "Enter a port from 1 to 65535",
      });
    if (values.connection.username && !secretWillBeSet(values.connection.password))
      context.addIssue({
        code: "custom",
        path: ["connection", "password"],
        message: "Enter the password for this user",
      });
  });
const RETRY_LAYERS = [
  { scope: "workspace", label: "the workspace", value: true },
  { scope: "organisation", label: "Northstar Studio", value: false },
] as const;
const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

function RelaySettings({
  open,
  onOpenChange,
  preview = false,
  loading = false,
  saveDisabledReason,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  preview?: boolean;
  loading?: boolean;
  saveDisabledReason?: string;
}) {
  const [saved, setSaved] = useState<RelayValues>(SAVED);
  const [tab, setTab] = useState("general");
  const form = useAppForm({
    ...settingsFormBehaviour,
    defaultValues: saved,
    validators: { onDynamic: relaySchema },
    onSubmit: async ({ value }) => {
      await wait(500);
      // The server checks what the browser cannot: does the host answer?
      if (value.connection.host.includes("invalid"))
        throw new SettingsSaveError("Cedar Annex SMTP relay was not saved", {
          "connection.host": `No mail server answers at ${value.connection.host}`,
        });
      const password = value.connection.password;
      setSaved({
        ...value,
        connection: {
          ...value.connection,
          password: secretValue(
            password.action === "replace"
              ? true
              : password.action === "clear"
                ? false
                : password.stored,
          ),
        },
      });
    },
  });
  const retry = useStore(form.store, (state) => state.values.policy.retry);
  const inherited = resolveSetting(
    [...RETRY_LAYERS, { scope: "relay", label: "this relay", value: retry }],
    true,
  );
  return (
    <EntitySettingsDialog
      open={open}
      onOpenChange={onOpenChange}
      preview={preview}
      loading={loading}
      saveDisabledReason={saveDisabledReason}
      form={form}
      tab={tab}
      onTabChange={setTab}
      media={
        <EntityIdentity
          tier="icon"
          name="Cedar Annex SMTP relay"
          kind="Mail relay"
          icon={<IconMail />}
          state={{ id: "up", label: "Sending", tone: "success" }}
        />
      }
      subtitle="smtp.northstar.example · Northstar Studio"
      entityName="Cedar Annex SMTP relay"
      onSaveError={(error) =>
        toast.danger(error instanceof Error ? error.message : "Not saved", {
          description: "Fix the marked fields and save again.",
        })
      }
      tabs={[
        {
          value: "general",
          label: "General",
          icon: <IconSettings />,
          fields: ["general"],
          content: (
            <>
              <form.AppField name="general.name">
                {(field) => <field.TextField label="Name" width="medium" required />}
              </form.AppField>
              <form.AppField name="general.hidden">
                {(field) => (
                  <field.SwitchRow
                    label="Hide from lists"
                    description="It stays reachable by link."
                  />
                )}
              </form.AppField>
            </>
          ),
        },
        {
          value: "connection",
          label: "Connection",
          icon: <IconGlobe />,
          fields: ["connection"],
          content: (
            <>
              <form.AppField name="connection.host">
                {(field) => (
                  <field.TextField
                    label="Host"
                    width="medium"
                    spellCheck={false}
                    hint="Try a host with “invalid” in it to see a server error."
                  />
                )}
              </form.AppField>
              <form.AppField name="connection.port">
                {(field) => (
                  <field.NumberField label="Port" width="short" format={{ useGrouping: false }} />
                )}
              </form.AppField>
              <form.AppField name="connection.username">
                {(field) => (
                  <field.TextField label="User" width="medium" optional autoComplete="off" />
                )}
              </form.AppField>
              <form.AppField name="connection.password">
                {() => <SecretField label="Password" secretName="password" width="medium" />}
              </form.AppField>
              <TestButton
                fields={["Server", "TLS", "Auth"]}
                onTest={async () => {
                  await wait(700);
                  const { port, host } = form.state.values.connection;
                  if (port !== 587 && port !== 25)
                    return {
                      ok: false,
                      summary: `Connection refused on port ${port ?? "—"} — relays usually answer on 587`,
                    };
                  return {
                    ok: true,
                    summary: `${host} answered in 42 ms`,
                    details: {
                      Server: "Postfix 3.8",
                      TLS: "STARTTLS · TLS 1.3",
                      Auth: "PLAIN accepted",
                    },
                  };
                }}
              >
                Test connection
              </TestButton>
            </>
          ),
        },
        {
          value: "policy",
          label: "Policy",
          icon: <IconLayers />,
          fields: ["policy"],
          content: (
            <>
              <form.AppField name="policy.retry">
                {(field) => (
                  <InheritedSetting
                    label="Retry failed sends"
                    source={inherited.inherited.source?.label ?? "the workspace"}
                    inheritedValue={inherited.inherited.value ? "On" : "Off"}
                    overridden={field.state.value !== null}
                    onOverride={() => field.handleChange(!inherited.inherited.value)}
                    onReset={() => field.handleChange(null)}
                    scope="this relay"
                    control={
                      <Switch
                        checked={field.state.value ?? false}
                        onCheckedChange={(checked) => field.handleChange(checked)}
                        aria-label="Retry failed sends"
                      />
                    }
                  />
                )}
              </form.AppField>
              <form.AppField name="policy.dailyLimit">
                {(field) => <field.NumberField label="Daily limit" unit="messages" width="short" />}
              </form.AppField>
            </>
          ),
        },
      ]}
    />
  );
}

/* ── Building blocks on their own ──────────────────────────────────────────── */
function Inherited() {
  const [photo, setPhoto] = useState<boolean | null>(null);
  const [snmp, setSnmp] = useState(false);
  return (
    <div className="flex w-full max-w-[var(--form-measure)] flex-col gap-4">
      <InheritedSetting
        label="Show signed-in user's photo"
        source="Northstar Studio"
        inheritedValue="On"
        overridden={photo !== null}
        onOverride={() => setPhoto(false)}
        onReset={() => setPhoto(null)}
        scope="this device"
        control={
          <Switch
            checked={photo ?? false}
            onCheckedChange={(checked) => setPhoto(checked)}
            aria-label="Show signed-in user's photo"
          />
        }
      />
      <InheritedSetting
        label="Credentials"
        source="the workspace"
        inheritedValue="v2c · port 161"
        overridden={snmp}
        onOverride={() => setSnmp(true)}
        onReset={() => setSnmp(false)}
        scope="this device"
      >
        <Field label="User">
          <Input defaultValue="glass-ux-monitor" width="medium" />
        </Field>
      </InheritedSetting>
      <InheritedSetting
        label="Daily limit"
        source="the workspace"
        inheritedValue="5,000"
        overridden={false}
        onOverride={() => undefined}
        onReset={() => undefined}
        disabledReason="Only workspace admins can override this"
      />
    </div>
  );
}

